def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = min possible tail of an inc subseq of length i+1
    for x in nums:
        # find position to replace (first >= x) for strictly increasing use >
        # For strictly increasing, we use bisect_left on tails with x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

