def solve(a,b):
    if len(a) < len(b):
        a,b=b,a
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]+[0]*len(b)
        for j,cb in enumerate(b,1):
            if ca==cb:
                cur[j]=prev[j-1]
            else:
                cur[j]=1+min(prev[j],cur[j-1],prev[j-1])
        prev=cur
    return prev[-1]

